@extends('layouts.admin') @section('title','Comments') @section('page-title','Comment Moderation') @section('content')<div class="admin-heading"><div><h1>Comments</h1><p>Review and moderate reader discussions.</p></div></div><section class="admin-card"><table class="admin-table"><tr><th>Reader</th><th>Comment</th><th>Post</th><th>Status</th></tr>@forelse($comments as $comment)<tr><td><b>{{$comment->user_name}}</b><br><small>{{$comment->user_email}}</small></td><td>{{Str::limit($comment->comment,100)}}</td><td>{{Str::limit($comment->post?->title,35)}}</td><td><form class="admin-actions" method="post" action="{{route('dashboard.comments.update',$comment)}}">@csrf @method('patch')<select name="status"><option @selected($comment->status==='pending')>pending</option><option @selected($comment->status==='approved')>approved</option><option @selected($comment->status==='rejected')>rejected</option></select><button><i class="fas fa-save"></i></button></form></td></tr>@empty<tr><td colspan="4" class="empty-admin">No comments found.</td></tr>@endforelse</table><div class="pagination">{{$comments->links()}}</div></section>@endsection
